5: import { stage6Sentences } from './model-stage6.js';
6: export const TICK_MS = 100;
7: const QUEUE_BAR_SATURATION = 20; // bar reads full at 20 queued requests
8: // Total hops per stage's trace shape (trace.js, trace-stage6.js and
9: // engine.traceHop agree). Stage 6's hosted shape is 9: the DNS ask + answer
10: // plus the stage-5 chain's wire hops (its emit hop is the browser's
11: // composition, not a wire frame).
12: const TOTAL_HOPS = { 1: 4, 2: 5, 3: 6, 4: 7, 5: 8, 6: 9 };
