// Compare tray pure contracts (b5 brief §1). Runs are the shape the panel
// pushes: { run, label, hops, entries } with entries in hop order.
describe('compare tray contracts', () => {
  const makeRun = (id, hops, textOf = (h) => `hop ${h} frame text`) => ({
    run: id,
    label: `/run-${id}`,
    hops,
    entries: Array.from({ length: hops }, (_, i) => ({ hop: i + 1, text: textOf(i + 1) })),
  });

  it('aligns unequal 9-by-6 runs into 9 rows with the right side an em-dash on rows 7-9', () => {
    // Named counter-example (brief): nothing drops — the exhausted side
    // renders `—`, exactly over max(left.hops, right.hops) rows.
    const left = makeRun(1, 9);
    const right = makeRun(2, 6);
    const rows = alignCompareRows(left, right);
    expect(rows).toHaveLength(9);
    expect(rows.map((r) => r.n)).toEqual([1, 2, 3, 4, 5, 6, 7, 8, 9]);
    expect(rows[6]).toEqual({ n: 7, left: 'hop 7 frame text', right: '—' });
    expect(rows[7].right).toBe('—');
    expect(rows[8].right).toBe('—');
    expect(rows[0].right).toBe('hop 1 frame text');
  });

  it('aligns equal runs hop-for-hop with no em-dash cells', () => {
    const rows = alignCompareRows(makeRun(1, 4), makeRun(2, 4));
    expect(rows).toHaveLength(4);
    for (const row of rows) {
      expect(row.left).not.toBe('—');
      expect(row.right).not.toBe('—');
    }
  });

  it('passes entry texts through verbatim — byte-identical, never mutated', () => {
    // PINS: the tray renders journey-log entry texts; minting or rewriting
    // hop frames is a defect. The original run objects stay untouched too.
    const texts = ['10.1 -> 10.2 | 200 Welcome to the home page', 'routed 10.2 -> 10.1 (GET /)'];
    const left = makeRun(1, 2, (h) => texts[h - 1]);
    const right = makeRun(2, 2);
    const beforeLeft = JSON.stringify(left);
    const beforeRight = JSON.stringify(right);
    const rows = alignCompareRows(left, right);
    expect(rows[0].left).toBe(texts[0]);
    expect(rows[1].left).toBe(texts[1]);
    expect(JSON.stringify(left)).toBe(beforeLeft);
    expect(JSON.stringify(right)).toBe(beforeRight);
  });

  it('fills slot A first, slot B second, and shifts A <- old B / B <- new on a third run', () => {
    const empty = { a: null, b: null };
    const r1 = makeRun(1, 4);
    const r2 = makeRun(2, 6);
    const r3 = makeRun(3, 4);
    const first = nextCompareSlots(empty, r1);
    expect(first).toEqual({ a: r1, b: null, changed: true });
    const second = nextCompareSlots(first, r2);
    expect(second).toEqual({ a: r1, b: r2, changed: true });
    const third = nextCompareSlots(second, r3);
    expect(third.a).toBe(r2);
    expect(third.b).toBe(r3);
    expect(third.changed).toBe(true);
  });

  it('re-pushing the right slot run is a no-op — changed:false, slots unchanged', () => {
    const slots = { a: makeRun(1, 4), b: makeRun(2, 6) };
    const again = nextCompareSlots(slots, makeRun(2, 6));
    expect(again.changed).toBe(false);
    expect(again.a).toBe(slots.a);
    expect(again.b).toBe(slots.b);
  });

  it('ignores tick-shaped and entry-less runs — the trace-runs-only counter-example', () => {
    // Brief spell-out: runs with hops < 2 or no hop entries are rejected. A
    // crowd tick ({ hops: 0 }) must never enter the slots, so starting the
    // crowd cannot shift the two stored trace runs.
    const slots = { a: makeRun(1, 4), b: makeRun(2, 6) };
    for (const bad of [
      { run: 9, label: 'tick', hops: 0, entries: [] },
      { run: 9, label: 'tick', hops: 1, entries: [{ hop: 1, text: 'tick frame' }] },
      { run: 9, label: 'tick', hops: 4, entries: [] },
      null,
    ]) {
      const next = nextCompareSlots(slots, bad);
      expect(next.changed).toBe(false);
      expect(next.a).toBe(slots.a);
      expect(next.b).toBe(slots.b);
    }
  });

  it('stores a copied entry snapshot at push time, keeping texts verbatim', () => {
    // Snapshot-at-completion: the stored run's entries are copies, immune to
    // later live-log trims/relabels, and the copied texts are identical.
    const r1 = makeRun(1, 4);
    const first = nextCompareSlots({ a: null, b: null }, r1);
    expect(first.a.entries).toHaveLength(4);
    expect(first.a.entries.map((e) => e.text)).toEqual(r1.entries.map((e) => e.text));
    expect(first.a.entries[0]).not.toBe(r1.entries[0]);
  });
});

