1: // guard-claims — factory-kit CLAIM-LANGUAGE.md, mechanically enforced
2: // (strict mode). Every comment paragraph in js/**, css/**, test/**, e2e/**
3: // obeys three rules:
4: //   1. At most one claim keyword (CHECKS:, PINS:, DOCUMENTS:) per paragraph.
5: //   2. Guarantee words (guarantees, always, never, ensures, will) may appear
6: //      ONLY inside CHECKS: or PINS: paragraphs — never in untagged comments
7: //      and never in DOCUMENTS: paragraphs ("description of behavior, carrying
8: //      no guarantee").
9: //   3. Non-vacuity: fails if 0 source files or 0 claim tags are scanned.
10: import { readFileSync, readdirSync, statSync } from 'node:fs';
11: import { join, relative, sep, extname } from 'node:path';
12: 
13: const SOURCE_DIRS = ['js', 'css', 'test', 'e2e'];
14: const SOURCE_EXT = new Set(['.js', '.css']);
15: const CLAIM_TAG = /\b(CHECKS|PINS|DOCUMENTS):/g;
16: const GUARANTEE_WORD = /\b(guarantees?|always|never|ensures?|will)\b/i;
17: 
18: function walk(dir, out = []) {
19:   for (const name of readdirSync(dir)) {
20:     const full = join(dir, name);
21:     if (statSync(full).isDirectory()) walk(full, out);
22:     else if (SOURCE_EXT.has(extname(full))) out.push(relative('.', full).split(sep).join('/'));
23:   }
24:   return out;
25: }
26: 
27: // Extract comment paragraphs [{ line, text }] while skipping '', "", and ``
28: // string literals (so template code in inspector-source.js and test titles
29: // in it('...') are not misread as comments).
30: function extractCommentParagraphs(src) {
31:   const blocks = [];
32:   let i = 0;
33:   let line = 1;
34:   while (i < src.length) {
35:     const ch = src[i];
36:     const next = src[i + 1];
37:     if (ch === '\n') {
38:       line += 1;
39:       i += 1;
40:     } else if (ch === "'" || ch === '"' || ch === '`') {
41:       const quote = ch;
42:       i += 1;
43:       while (i < src.length && src[i] !== quote) {
44:         if (src[i] === '\\') i += 1;
45:         if (src[i] === '\n') line += 1;
46:         i += 1;
47:       }
48:       i += 1;
49:     } else if (ch === '/' && next === '/') {
50:       const startLine = line;
51:       const end = src.indexOf('\n', i);
52:       const raw = (end === -1 ? src.slice(i + 2) : src.slice(i + 2, end)).trim();
53:       blocks.push({ kind: 'line', line: startLine, text: raw });
54:       i = end === -1 ? src.length : end;
55:     } else if (ch === '/' && next === '*') {
56:       const startLine = line;
57:       const end = src.indexOf('*/', i + 2);
58:       const raw = end === -1 ? src.slice(i + 2) : src.slice(i + 2, end);
59:       line += raw.split('\n').length - 1;
60:       blocks.push({ kind: 'block', line: startLine, text: raw.trim() });
61:       i = end === -1 ? src.length : end + 2;
62:     } else {
63:       i += 1;
64:     }
65:   }
66: 
67:   // Merge adjacent non-empty `//` lines into paragraphs; blank `//` or a new
68:   // leading claim keyword starts a fresh paragraph.
69:   const paragraphs = [];
70:   let current = null;
71:   for (const b of blocks) {
72:     if (b.kind === 'block') {
73:       if (current) paragraphs.push(current);
74:       current = null;
75:       if (b.text) paragraphs.push({ line: b.line, text: b.text });
76:     } else if (b.text === '') {
77:       if (current) paragraphs.push(current);
78:       current = null;
79:     } else if (
80:       current &&
81:       b.line === current.lastLine + 1 &&
82:       !/^(CHECKS|PINS|DOCUMENTS):/.test(b.text)
83:     ) {
84:       current.text += ` ${b.text}`;
85:       current.lastLine = b.line;
86:     } else {
87:       if (current) paragraphs.push(current);
88:       current = { line: b.line, lastLine: b.line, text: b.text };
89:     }
90:   }
91:   if (current) paragraphs.push(current);
92:   return paragraphs;
93: }
94: 
95: const files = SOURCE_DIRS.flatMap((d) => walk(d));
96: const errors = [];
97: let totalClaims = 0;
98: 
99: for (const file of files) {
100:   for (const p of extractCommentParagraphs(readFileSync(file, 'utf8'))) {
101:     const tags = [...p.text.matchAll(CLAIM_TAG)].map((m) => m[1]);
102:     totalClaims += tags.length;
103:     if (tags.length > 1) {
104:       errors.push(
105:         `${file}:${p.line} — multiple claim keywords (${tags.join(', ')}) in one comment paragraph.`,
106:       );
107:       continue;
108:     }
109:     const word = p.text.match(GUARANTEE_WORD);
110:     if (!word) continue;
111:     if (tags.length === 0) {
112:       errors.push(
113:         `${file}:${p.line} — bare guarantee word "${word[0]}" outside CHECKS:/PINS: ("${p.text.slice(0, 72)}…")`,
114:       );
115:     } else if (tags[0] === 'DOCUMENTS') {
116:       errors.push(
117:         `${file}:${p.line} — DOCUMENTS: carries no guarantee, but found "${word[0]}" ("${p.text.slice(0, 72)}…")`,
118:       );
119:     }
120:   }
121: }
122: 
123: if (files.length === 0 || totalClaims === 0) {
124:   console.error('guard-claims: selection or claim count is 0 — guard is vacuous.');
125:   process.exit(1);
126: }
127: if (errors.length > 0) {
128:   for (const e of errors) console.error(`guard-claims: ${e}`);
129:   console.error(`guard-claims: ${errors.length} violation(s).`);
130:   process.exit(1);
131: }
132: console.log(
133:   `guard-claims: OK (${files.length} files, ${totalClaims} claim(s), strict CHECKS/PINS/DOCUMENTS)`,
134: );

